mappings.INQUIRY.response:
body.reply = "VALIDATE" and body.status = "ACTIVE" and body.merchantRef != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.merchantRef}
: body.fault = "Client" and body.code != ""
  ? {"outcome": "FAILED", "code": body.code, "message": body.message}
: {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"}

mappings.PAY.response:
body.reply = "NOTIFY" and body.status = "RECEIVED" and body.notifyRef != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.notifyRef, "code": body.code != "" ? body.code}
: body.fault = "Client" and body.code != ""
  ? {"outcome": "FAILED", "code": body.code, "message": body.message}
: {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"}

mappings.REVERSE.response:
body.reply = "REFUND" and body.status = "REFUNDED" and body.refundRef != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.refundRef, "code": body.code != "" ? body.code}
: body.fault = "Client" and body.code != ""
  ? {"outcome": "FAILED", "code": body.code, "message": body.message}
: {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"}

mappings.STATUS_QUERY.response:
body.reply = "QUERY" and body.status = "RECEIVED" and body.notifyRef != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.notifyRef}
: body.reply = "QUERY" and body.status = "NOT_FOUND"
  ? {"outcome": "NOT_FOUND"}
: body.fault = "Client" and body.code != ""
  ? {"outcome": "FAILED", "code": body.code, "message": body.message}
: {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"}
